void free_process_user_page(PTE* pgdir)
{
    if (pgdir == NULL || pgdir == (PTE *)PGDIR_PA) {
        return;
    }

    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
    for (int vpn2 = 0; vpn2 < NUM_PTE_ENTRY; vpn2++) {
        if (vpn2 == 0x101 || !get_attribute(pgdir_kva[vpn2], _PAGE_PRESENT)) {
            continue;
        }

        PTE *second_level_pgdir =
            (PTE *)pa2kva(get_pa(pgdir_kva[vpn2]));
        for (int vpn1 = 0; vpn1 < NUM_PTE_ENTRY; vpn1++) {
            if (!get_attribute(second_level_pgdir[vpn1], _PAGE_PRESENT)) {
                continue;
            }

            PTE *last_level_pgdir =
                (PTE *)pa2kva(get_pa(second_level_pgdir[vpn1]));
            for (int vpn0 = 0; vpn0 < NUM_PTE_ENTRY; vpn0++) {
                PTE entry = last_level_pgdir[vpn0];
                if (get_attribute(entry, _PAGE_PRESENT)) {
                    uintptr_t pa = get_pa(entry);
                    int shm_slot = find_shm_slot(pa);
                    if (shm_slot >= 0) {
                        shm_page[shm_slot].count--;
                        if (shm_page[shm_slot].count == 0) {
                            free_user_page(pa);
                            shm_page[shm_slot].pa = 0;
