   147	// select a user page to write to disk (NRU), returns pa
   148	ptr_t selete_page()
   149	{
   150	    ptr_t ret = 0;
   151	    int best_class = 4;
   152	
   153	    for (int i = 0; i < USER_PAGE_NUM; i++) {
   154	        if (!user_page[i].valid || user_page[i].pin || user_page[i].pgtable == NULL) {
   155	            continue;
   156	        }
   157	
   158	        PTE *pgtable = user_page[i].pgtable;
   159	        if (!get_attribute(*pgtable, _PAGE_PRESENT)) {
   160	            continue;
   161	        }
   162	
   163	        int accessed = get_attribute(*pgtable, _PAGE_ACCESSED);
   164	        int dirty = get_attribute(*pgtable, _PAGE_DIRTY);
   165	        int page_class = (accessed ? 2 : 0) + (dirty ? 1 : 0);
   166	
   167	        if (page_class < best_class) {
   168	            best_class = page_class;
   169	            ret = num2pa(i);
   170	            if (best_class == 0) {
   171	                break;
   172	            }
   173	        }
   174	
   175	        if (accessed) {
   176	            clear_attribute(pgtable, _PAGE_ACCESSED);
   177	        }
   178	    }
   179	
   180	    assert(ret != 0);
   181	    return ret;
   182	}
